data.minimal_example:
import 'package:filepicker_windows/filepicker_windows.dart';

final picker = OpenFilePicker()
  ..filterSpecification = {
    'Text Document (*.txt)': '*.txt',
    'All Files': '*.*',
  }
  ..title = 'Select a file';

final file = picker.getFile();
if (file != null) {
  print('Selected: ${file.path}');
}
